\label{thm:deterministic_limit}
Let $H=WQ\widetilde A-I$. If $H$ is invertible, then, as
$t\to\infty$, the process $\mathbf Z_t$ converges
almost surely to the deterministic limit
\begin{equation} \label{deter_limit}
\mbox{${\mathbf Z}$}^*=-C(WQ\widetilde A-I)^{-1}.
\end{equation}

\label{thm:invertibility_1}
    Assume that, for every critical vertex $i$,
$\mu_{ji}\ne0$ for every $j\in N(i)$.
 Then $H$ is invertible if either
of the following conditions holds:
    \begin{enumerate}[(i)]
        \item there exists a mixed-sampling vertex and either $\mathcal G$ contains an odd cycle or two mixed-sampling vertices are connected by a directed path of odd length;
        \item there exists a subcritical vertex and either $\mathcal G$ contains an odd cycle or two subcritical vertices are connected by a directed path of odd length.
    \end{enumerate}
Consequently, by Theorem~\ref{thm:deterministic_limit}, \[ \mbox{${{\mathbf Z}}$}_t \xrightarrow{\mathrm{a.s.}} -CH^{-1}. \]

\label{thm:joint_compact_LIL_SA}

Assume that \(\operatorname{Re}(\lambda_1)<1/2\), that \(\mbox{${{\mathbf Z}}$}_t\) admits a deterministic limit, and that \(\Gamma\) is positive definite. Then, with probability one, the sequence $ \left\{
        \sqrt{\frac{t}{2\log\log t}}\,
        (\mbox{${{\mathbf Z}}$}_t-\mbox{${\mathbf Z}$}^*)
        \right\}_{t\ge 3}$
is relatively compact in $\mbox{${\mathbb R}$}^N$, and its set of limit points is the ellipsoid  $\mathcal E_{\mathrm{LIL}}
        =
        \left\{
        x\in \mbox{${\mathbb R}$}^N:
        x\Sigma_{\infty}^{-1}x^\top \le 1
        \right\}.$

\label{thm:AS_average}
Assume {\bf (B)} holds and
$\mu^{out}_{\mathcal P}-\mu^{out}_{\mathcal D}<1$. Then, as $t\to\infty$,
\begin{equation}
\big(
Z_t^{\mathcal P} , 
Z_t^{\mathcal D}
 \big)
\xrightarrow{a.s.}
\frac{d_1+d_2}
{\mu^{out}_{\mathcal D}-\mu^{out}_{\mathcal P}+1}
\big(
\mu^{out}_{\mathcal P}, 
\mu^{out}_{\mathcal D}
\big).
\end{equation}
Further, $\left( Z_t^{P_1}+Z_t^{D_1}, Z_t^{P_1}+Z_t^{P_2}, Z_t^{D_1}+Z_t^{D_2} \right)  and  \left( Z_t^{P_2}+Z_t^{D_2}, Z_t^{P_1}+Z_t^{P_2}, Z_t^{D_1}+Z_t^{D_2} \right)$ converge almost surely to $\mu^{out}(d_1+d_2)(1,1,1)$ and $Z_t^{P_1},Z_t^{P_2},Z_t^{D_1}$ and $Z_t^{D_2}$ admit almost sure limits, provided $\mu^{out}_{\mathcal P} =\mu^{out}_{\mathcal D} = \mu^{out}$.

\label{thm:randomlimit}
Suppose that {\bf (B)}, {\bf (C)}, and {\bf (D)}
hold and that $p_1+p_2=d_1+d_2$. Then $\mbox{${{\mathbf Z}}$}_t(I-\tilde J)\to{\bf 0}$ almost surely as $t\to\infty$.

\label{prop:Var}
Suppose {\rm \bf (D)} holds. Let $U$ be an $N\times N$ matrix such that
$\mathbf{1}_{\mathcal D}\widetilde{A} U=0$, $Q\widetilde{A}U=UQ\widetilde{A}$, and $\hat vU=0$. Let
$\nu_1,\ldots,\nu_N$ be the eigenvalues of
$I-Q\widetilde{A}$, and set
$\nu^*:=\min\{\operatorname{Re}(\nu_i):\nu_i\neq 0\}>0$. Then
\begin{itemize}
    \item $\mbox{${\mathbb E}$}[\mbox{${{\mathbf Z}}$}_tU]=\mathcal{O}\left(t^{-\nu^*}\right)$.
    \item $\operatorname{Var}(\mbox{${{\mathbf Z}}$}_tU)=\mathcal{O}\left(t^{-\delta}\right)$ for some $\delta>0$.
\end{itemize}

From \eqref{noderecurnew} we get
\begin{align*}
Z_{t+1}(i)
&= Z_t(i) + \frac{1}{t+1} \left(\Delta M_{t+1}(i) +
\sum_{j\in N(i)\cap\mathcal P}\mu_{ji}Z_t(j) \right)
\\
&\quad
+ \frac{1}{t+1} \left( \sum_{j\in N(i)\cap\mathcal D}\mu_{ji}(1-Z_t(j))-Z_t(i)\right).
\end{align*}

For $U\subseteq\mbox{${\mathcal V}$}$, write
$\Delta M_{t+1}^{U}:=\sum_{i\in U}\Delta M_{t+1}(i)$.
By the block structure of the adjacency matrix and
{\rm \bf (B)}, we obtain
\begin{align*}
Z_{t+1}^{P_1}
&= Z_t^{P_1} + \frac{1}{t+1} \left[ \mu^{out}_{\mathcal P}
\left( Z_t^{P_1}-Z_t^{D_1}+d_1 \right) - Z_t^{P_1} \right] + \frac{\Delta M_{t+1}^{P_1}}{t+1},
\\
Z_{t+1}^{D_1}
&= Z_t^{D_1} + \frac{1}{t+1} \left[ \mu^{out}_{\mathcal D}
\left( Z_t^{P_2}-Z_t^{D_2}+d_2 \right) - Z_t^{D_1} \right] + \frac{\Delta M_{t+1}^{D_1}}{t+1},
\\
Z_{t+1}^{P_2}
&= Z_t^{P_2} + \frac{1}{t+1} \left[ \mu^{out}_{\mathcal P}
\left(Z_t^{P_2}-Z_t^{D_2}+d_2 \right) - Z_t^{P_2} \right]
+ \frac{\Delta M_{t+1}^{P_2}}{t+1},
\\
Z_{t+1}^{D_2}
&= Z_t^{D_2} + \frac{1}{t+1} \left[ \mu^{out}_{\mathcal D}
\left(Z_t^{P_1}-Z_t^{D_1}+d_1 \right) - Z_t^{D_2} \right]
+ \frac{\Delta M_{t+1}^{D_2}}{t+1}.
\end{align*}
Adding the $P_1$ and $P_2$ equations gives
\begin{align*}
Z_{t+1}^{\mathcal P}
&= Z_t^{\mathcal P} + \frac{1}{t+1} \left[ (\mu^{out}_{\mathcal P}-1)Z_t^{\mathcal P} -\mu^{out}_{\mathcal P}Z_t^{\mathcal D} +\mu^{out}_{\mathcal P}(d_1+d_2)
\right] + \frac{\Delta M_{t+1}^{\mathcal P}}{t+1},
\end{align*}
Similarly,
\begin{align*}
Z_{t+1}^{\mathcal D}
&= Z_t^{\mathcal D} + \frac{1}{t+1} \left[ \mu^{out}_{\mathcal D}Z_t^{\mathcal P} -(\mu^{out}_{\mathcal D}+1)Z_t^{\mathcal D} +\mu^{out}_{\mathcal D}(d_1+d_2)
\right] + \frac{\Delta M_{t+1}^{\mathcal D}}{t+1}.
\end{align*}
Thus, $(Z_t^{\mathcal P},Z_t^{\mathcal D})$ is a two-dimensional
stochastic approximation with limiting ODE
\begin{equation}\label{ode1}
\frac{d}{dt}
\begin{pmatrix}
Z_t^{\mathcal P}\\
Z_t^{\mathcal D}
\end{pmatrix}
=
\begin{pmatrix}
\mu^{out}_{\mathcal P}-1
&
-\mu^{out}_{\mathcal P}
\\
\mu^{out}_{\mathcal D}
&
-\mu^{out}_{\mathcal D}-1
\end{pmatrix}
\begin{pmatrix}
Z_t^{\mathcal P}\\
Z_t^{\mathcal D}
\end{pmatrix}
+
(d_1+d_2)
\begin{pmatrix}
\mu^{out}_{\mathcal P}\\
\mu^{out}_{\mathcal D}
\end{pmatrix}.
\end{equation}
The eigenvalues of the matrix in \eqref{ode1} are
$-1$ and
$\mu^{out}_{\mathcal P}
-\mu^{out}_{\mathcal D}-1$.
Hence, if
$\mu^{out}_{\mathcal P}
-\mu^{out}_{\mathcal D}<1$,
the equilibrium is stable and is given by
\[
\frac{d_1+d_2}
{\mu^{out}_{\mathcal D}-\mu^{out}_{\mathcal P}+1}
\begin{pmatrix}
\mu^{out}_{\mathcal P}\\
\mu^{out}_{\mathcal D}
\end{pmatrix}.
\]
The stochastic approximation convergence theorem therefore gives the claimed almost sure convergence. Now suppose
$\mu^{out}_{\mathcal P}
=
\mu^{out}_{\mathcal D}
=
\mu^{out}$.
Since
$\mu^{out}_{\mathcal P}+\mu^{out}_{\mathcal D}=1$,
we necessarily have
$\mu^{out}=\frac{1}{2}$.
Using the four recursions above, the process $\left( Z_t^{P_1}+Z_t^{D_1}, Z_t^{P_1}+Z_t^{P_2},
Z_t^{D_1}+Z_t^{D_2}
\right)$ satisfies a stochastic approximation scheme with drift function $\frac{d_1+d_2}{2}(1,1,1) + \left(
Z_t^{P_1}+Z_t^{D_1},
Z_t^{P_1}+Z_t^{P_2},
Z_t^{D_1}+Z_t^{D_2}
\right)\Gamma$,
where $\Gamma=
\begin{pmatrix}
-1 & 0 & 0\\
\frac12 & -\frac12 & \frac12\\
-\frac12 & -\frac12 & -\frac32
\end{pmatrix}$. The only eigenvalue of $\Gamma$ is $-1$. Hence
\[
\left(
Z_t^{P_1}+Z_t^{D_1},
Z_t^{P_1}+Z_t^{P_2},
Z_t^{D_1}+Z_t^{D_2}
\right)
\xrightarrow{a.s.}
\frac{d_1+d_2}{2}(1,1,1).
\]
Similarly,
\[
\left(
Z_t^{P_2}+Z_t^{D_2},
Z_t^{P_1}+Z_t^{P_2},
Z_t^{D_1}+Z_t^{D_2}
\right)
\xrightarrow{a.s.}
\frac{d_1+d_2}{2}(1,1,1).
\]
By Lemma~\ref{lem:GPA_structure} and
Remark~\ref{d1d2},
$Z_t^{P_1}+Z_t^{D_2}-Z_t^{P_2}-Z_t^{D_1}$ admits an almost sure limit.
Since $Z_t^{P_1}+Z_t^{P_2}$ has an almost sure deterministic limit, it follows that
$2Z_t^{P_1}+Z_t^{D_2}-Z_t^{D_1}$ admits an almost sure limit. Combining this
with the deterministic limit of $Z_t^{D_1}+Z_t^{D_2}$, we get that
$Z_t^{P_1}-Z_t^{D_1}$ admits an almost sure limit. Since
$Z_t^{P_1}+Z_t^{D_1}$ also has an almost sure deterministic limit, both
$Z_t^{P_1}$ and $Z_t^{D_1}$ admit almost sure limits. Similarly,
$Z_t^{P_2}$ and $Z_t^{D_2}$ also have almost sure limits.

Let $v$ be a real left eigenvector of $Q\widetilde{A}-I$ corresponding to the eigenvalue $0$. Since the matrix $Q\widetilde{A}-I$ is real and the eigenvalue is real, this entails no loss of generality. Normalize $v$ so that $\max_i |v_i|=1$. Choose $j$ such that $|v_j|=1$, and replacing $v$ by $-v$ if necessary, assume that $v_j=1$.

Assume first that $j \in P_1$. For this node, the total reinforcement received from its in-neighbors comes from nodes in $P_1 \cup D_1$. Hence
\begin{equation*}
\sum_{i \in P_1} \mu_{ij}
+
\sum_{i \in D_1} \mu_{ij} = 1
\end{equation*}
On the other hand, the $j$-th component of the left eigenvector equation
$vQ\widetilde{A}=v$ gives
\begin{equation*}
\sum_{i \in P_1} v_i \mu_{ij}
-
\sum_{i \in D_1} v_i \mu_{ij}=1.
\end{equation*}
Comparing the two expressions  and using $|v_i|\leq 1$, the equality can hold only if, for every $i$ such that $\mu_{ij}>0$,
\begin{itemize}
    \item $v_i=1$ for $i\in P_1$,
    \item $v_i=-1$ for $i\in D_1$.
\end{itemize}

Now fix any $k\in P_1$. We may choose a path from $k$ to $j$ whose block pattern is one of the following:
\begin{itemize}
    \item $k \rightsquigarrow_{P_1} j$,
    \item $k \rightsquigarrow_{P_1} D_2 \rightarrow D_1 \rightarrow P_1 \rightsquigarrow_{P_1} j$,
    \item $k \rightsquigarrow_{P_1} D_2 \rightarrow P_2 \rightsquigarrow_{P_2} D_1 \rightarrow P_1 \rightsquigarrow_{P_1} j$.
\end{itemize}
In the first case, repeatedly applying the previous argument backwards along the path gives $v_k=1$. In the second case, the path contains a node $k'\in D_1$ with $v_{k'}=-1$. For such a node, the eigenvector equation gives
\begin{equation*}
v_{k'}
=
\sum_{i \in P_2} v_i \mu_{ik'}
-
\sum_{i \in D_2} v_i \mu_{ik'}.
\end{equation*}
Using the same comparison argument and backtracking along the path gives $v_k=1$. The third case is identical, with the same argument applied through the intermediate segment in $P_2$. Therefore $v_k=1$ for every $k\in P_1$. The same argument applied to the other blocks gives
\[
v_i=1 \quad \text{for all } i\in P_1\cup D_2,
\qquad
v_i=-1 \quad \text{for all } i\in P_2\cup D_1.
\]
Thus $v=\hat v$. If the initial choice of sign was the opposite, then $v=-\hat v$. If $j$ belongs to any of the other three partitions, the same argument, with the signs changed according to the partition containing $j$, gives the same conclusion. Hence $v=\hat v$ or $v=-\hat v$, and the real left eigenspace is spanned by $\hat v$.

\label{ex:4cycle}
Let $k=4$. Then,  the two-step components are $\mbox{${\mathcal V}$}_1=\{1,3\}$ and $\mbox{${\mathcal V}$}_2=\{2,4\}$, and
\[
\det(WQ\widetilde A-I)
=
\left(1-(2q_1-1)(2q_3-1)\mu_{12}\mu_{34}\right)
\left(1-(2q_2-1)(2q_4-1)\mu_{23}\mu_{41}\right).
\]
In the figures below, a blue vertex is preferential, a red
vertex is de-preferential, an edge labelled P is of P\'olya type and an edge labelled NP is of non-P\'olya type. A white vertex carries no colour-coded assumption; its status is only what is specified in the corresponding case.

\begin{itemize}
\item[(i)] Let $q_2=q_4=1$ and $\mu_{23}=\mu_{41}=1$.
