\label{thm:AS_average_URNS}
Assume (B1) and (B2) hold and
$\frac{m^{out}_{\mathcal P}}{\bar{m}^{in}_{\mathcal P}}
-\frac{m^{out}_{\mathcal D}}{\bar{m}^{in}_{\mathcal D}}<1$. Then, as
$t \to \infty$,
$$
\begin{pmatrix} Z_t^{\mathcal P} \\  Z_t^{\mathcal D} \end{pmatrix}
\xrightarrow{a.s.}
\frac{d_1+d_2}
{\frac{m^{out}_{\mathcal D}}{\bar{m}^{in}_{\mathcal D}}
-\frac{m^{out}_{\mathcal P}}{\bar{m}^{in}_{\mathcal P}}+1}
\begin{pmatrix}
\frac{m^{out}_{\mathcal P}}{\bar{m}^{in}_{\mathcal P}}\\
\frac{m^{out}_{\mathcal D}}{\bar{m}^{in}_{\mathcal D}}
\end{pmatrix}.
$$
In addition, if
$\frac{m^{out}_{\mathcal P}}{\bar{m}^{in}_{\mathcal P}}
=\frac{m^{out}_{\mathcal D}}{\bar{m}^{in}_{\mathcal D}}=r$ (equal-ratio condition), then
$(Z_t^{P_1}+Z_t^{D_1}, Z_t^{P_1}+Z_t^{P_2}, Z_t^{D_1}+Z_t^{D_2})$
and
$(Z_t^{P_2}+Z_t^{D_2}, Z_t^{P_1}+Z_t^{P_2}, Z_t^{D_1}+Z_t^{D_2})$
converge almost surely to $r(d_1+d_2)(1,1,1)$. If the above equal-ratio
condition holds and (B3) holds, then
$Z_t^{P_1}, Z_t^{P_2}, Z_t^{D_1}$ and $Z_t^{D_2}$ admit almost sure limits. Furthermore, if
$m^{out}_{\mathcal P}=m^{out}_{\mathcal D}=\bar m^{in}/2$, then as
$t\to\infty$, $\bar Z_t\xrightarrow{a.s.}1/2$, provided
$p_1+p_2=d_1+d_2$. Moreover, if $p_1=p_2=d_1=d_2$, then, as $t\to\infty$,
\[
(\bar Z_t^{P_1}+\bar Z_t^{D_1},
\bar Z_t^{P_1}+\bar Z_t^{P_2},
\bar Z_t^{D_1}+\bar Z_t^{D_2},
\bar Z_t^{P_2}+\bar Z_t^{D_2})
\xrightarrow{a.s.}
(1,1,1,1).
\]

For $i\in[N]$,
\begin{equation}\label{recur_cycle}
Z_{t+1}(i)
=
Z_t(i)
+
\frac{\bar m^{in}}{T_{t+1}}
\begin{cases}
1-Z_t(\hat i)-Z_t(i)+\Delta M_{t+1}(i),
& \text{if } i\in\mathcal P,\\
Z_t(\hat i)-Z_t(i)+\Delta M_{t+1}(i),
& \text{if } i\in\mathcal D,
\end{cases}
\end{equation}
where $\Delta M_{t+1}(i)$ is a bounded martingale difference. Summing over the
four parts of the partition gives
\begin{equation}\label{cycle:P1P2}
Z_{t+1}^{P_1} = Z_t^{P_1} + \frac{\bar m^{in}}{T_{t+1}}
\left(p_1-Z_t^{D_1}-Z_t^{P_1}+\Delta M_{t+1}^{P_1}\right)
\text{ and }
Z_{t+1}^{P_2} = Z_t^{P_2} + \frac{\bar m^{in}}{T_{t+1}}
\left(p_2-Z_t^{D_2}-Z_t^{P_2}+\Delta M_{t+1}^{P_2}\right),
\end{equation}
and,
\begin{equation}\label{cycle:D1D2}
Z_{t+1}^{D_1} = Z_t^{D_1} + \frac{\bar m^{in}}{T_{t+1}} \left(Z_t^{P_2}-Z_t^{D_1}+\Delta M_{t+1}^{D_1}\right) \text{ and }
Z_{t+1}^{D_2} = Z_t^{D_2} +
\frac{\bar m^{in}}{T_{t+1}}
\left(Z_t^{P_1}-Z_t^{D_2}+\Delta M_{t+1}^{D_2}\right).
\end{equation}

From \eqref{cycle:P1P2} and \eqref{cycle:D1D2}, the process $S_t:=Z_t^{P_1}+Z_t^{D_2}-Z_t^{P_2}-Z_t^{D_1}$ is a bounded martingale, and hence admits an almost sure limit, say $S_\infty$. Next, define $V_t = \left( Z_t^{P_1}+Z_t^{D_1},\; Z_t^{P_1}+Z_t^{P_2},\; Z_t^{D_1}+Z_t^{D_2}
\right)$. Using \eqref{cycle:P1P2} and \eqref{cycle:D1D2}, we get
\[
V_{t+1}
=
V_t
+
\frac{\bar m^{in}}{T_{t+1}}
\left[
(p_1,p_1+p_2,0)
+
V_t
\begin{pmatrix}
-2 & 0 & 0\\
1 & -1 & 1\\
0 & -1 & -1
\end{pmatrix}
+
\Delta N_{t+1}
\right],
\]
where $\Delta N_{t+1}$ is a bounded martingale difference. The matrix above
has eigenvalues $-2$ and $-1\pm i$, and the corresponding ODE has the unique
stable equilibrium $(n,n,n)=(N/4,N/4,N/4)$. Hence, by the standard stochastic approximation argument, \(V_t\to(n,n,n)\)
almost surely. Thus \(Z_t^{P_1}+Z_t^{D_1}\), \(Z_t^{P_1}+Z_t^{P_2}\), and
\(Z_t^{D_1}+Z_t^{D_2}\) all converge almost surely to \(n\).

Combining these
three limits with \(S_t\to S_\infty\), we get
\(Z_t^{P_1},Z_t^{D_2}\to(S_\infty+2n)/4\) and
\(Z_t^{P_2},Z_t^{D_1}\to n-(S_\infty+2n)/4\) almost surely. Since each block
has size \(n\), setting \(\xi_\infty=(S_\infty+2n)/(4n)\) gives
\(\bar Z_t^{P_1},\bar Z_t^{D_2}\to\xi_\infty\) and
\(\bar Z_t^{P_2},\bar Z_t^{D_1}\to1-\xi_\infty\) almost surely.

\label{aux:duflo_martingale_estimate}
Let $(M_n)$ be a square-integrable martingale with increasing process $\langle M\rangle_n$, and set $\langle M\rangle_\infty:=\lim_{n\to\infty}\langle M\rangle_n$. Then:
\begin{itemize}
\item
On $\{\langle M\rangle_\infty<\infty\}$, $M_n\xrightarrow{\mathrm{a.s.}}M_\infty$, where $M_\infty$ is finite.

\item
On $\{\langle M\rangle_\infty=\infty\}$,
$M_n/\langle M\rangle_n\xrightarrow{\mathrm{a.s.}}0$. More precisely, for every $\gamma>0$, on $\{\langle M\rangle_\infty=\infty\}$,
\[
M_n
=
o\!\left(
\langle M\rangle_n^{1/2}
